归并排序

归并排序是一种基于分治法的稳定排序算法，其时间复杂度为 O(nlog⁡n)O(n \log n)O(nlogn)，空间复杂度为 O(n)O(n)O(n)。以下是其详细步骤、代码实现及优化：

------

**分步解释**

1. **分割**
    将数组递归地分成左右两半，直至每个子数组长度为1。

2. 合并

   将两个有序子数组合并为一个新的有序数组：

   - 比较子数组头部元素，选择较小者加入结果。
   - 将剩余元素按序拷贝到结果数组。

3. **递归终止条件**
    当子数组长度为1时，天然有序，直接返回。

```java
/**
 * 归并排序主方法（存在两处待修复问题）
 * 
 * @param arr   待排序数组
 * @param left  当前子数组左边界
 * @param right 当前子数组右边界
 */
public static void mergeSort(int[] arr, int left, int right) {
    // 递归终止条件：当子数组长度为1时无需继续分割
    if (left == right) {
        return;
    }

    // 问题1：计算中点的位运算需要用括号包裹，
    int mid = left + ((right - left) >> 1); 

    // 递归分割左半部分（左边界到中点）
    mergeSort(arr, left, mid);

    // 递归分割右半部分（中点+1到右边界）
    mergeSort(arr, mid + 1, right);

    // 合并已排序的子数组
    merge(arr, left, mid, right);
}

/**
 * 合并两个有序子数组（存在变量名冲突问题）
 * 
 * @param arr   原数组
 * @param left  左子数组起始位置
 * @param mid   左子数组结束位置/右子数组起始位置-1
 * @param right 右子数组结束位置
 */
public static void merge(int[] arr, int left, int mid, int right) {
    // 创建临时数组保存合并结果（可优化为复用同一临时数组）
    int[] help = new int[right - left + 1];
    int i = 0;        // 临时数组索引

    int p1 = left;    // 左子数组指针（起点=left）
    int p2 = mid + 1; // 右子数组指针（起点=mid+1）

    // 合并两个有序数组直到某一方耗尽
    while (p1 <= mid && p2 <= right) {
        help[i++] = arr[p1] <= arr[p2] ? arr[p1++] : arr[p2++];
    }

    // 复制剩余左子数组元素
    while (p1 <= mid) {
        help[i++] = arr[p1++];
    }

    // 复制剩余右子数组元素
    while (p2 <= right) {
        help[i++] = arr[p2++];
    }

    for (int j = 0; j < help.length; j++) { 
        arr[left + j] = help[j];
    }
}

```

小和问题

```java

public int smallSum(int[] arr) {
    if(arr.length < 2 || arr == null){
        return 0;
    }
    // 通过归并排序过程计算小和的总值
    return mergeSort(arr, 0, arr.length - 1); 
}

/**
 * 递归进行归并排序并累加小和
 * 
 * @param arr   目标数组（排序会修改原始数组）
 * @param left  当前子数组左边界
 * @param right 当前子数组右边界
 * @return 当前区间的小和累计值
 */
public static int mergeSort(int[] arr, int left, int right) {
    // 终止条件：单个元素的小和为0
    if (left == right) {
        return 0;
    }

    int mid = left + ((right - left) >> 1); 

    // 分治累加：左半小和 + 右半小和 + 合并过程的小和
    return mergeSort(arr, left, mid) 
         + mergeSort(arr, mid + 1, right) 
         + merge(arr, left, mid, right);
}

/**
 * 合并两个有序区间并计算小和（存在多个错误）
 * 
 * @param arr   原数组（将修改为有序）
 * @param left  左区间起点
 * @param mid   左区间终点/右区间起点-1
 * @param right 右区间终点
 * @return 当前合并过程产生的小和
 */
public static int merge(int[] arr, int left, int mid, int right) {
    int[] help = new int[right - left + 1]; // 合并用的临时数组
    int i = 0; // 临时数组指针
    int p1 = left, p2 = mid + 1; // 左右区间指针
    int smallSum = 0; // 累计当前合并阶段的小和

    while (p1 <= mid && p2 <= right) { 
        smallSum += arr[p1] < arr[p2] ? (right - p2 + 1) * arr[p1] : 0;

        // 合并操作（稳定排序需保持<=）
        help[i++] = arr[p1] < arr[p2] ? arr[p1++] : arr[p2++];
    }

    // 处理左区间剩余元素（不产生小和）
    while (p1 <= mid) {
        help[i++] = arr[p1++];
    }

    // 处理右区间剩余元素（不产生小和）
    while (p2 <= right) {
        help[i++] = arr[p2++]; 
    }

    // 将合并结果写回原数组对应位置
    for (i = 0; i < help.length; i++) {
        arr[left + i] = help[i];
    }
    return smallSum; 
}

```

逆序对问题

```java
class Solution {
    public int reversePairs(int[] record) {
        if(record.length < 2){
            return 0;
        }
       return mergeSort(record, 0, record.length - 1);
    }
    public static int mergeSort(int[] arr, int left, int right){
        int count = 0;
        if(left < right)  {


        int mid = left + ((right - left) >> 1);
        count = mergeSort(arr, left, mid) + mergeSort(arr, mid + 1, right) + merge(arr, left, mid, right);
    }
    return count;
    }
    public static int merge(int[] arr, int left, int mid, int right){
        int[] help = new int[right - left + 1];
        int i = 0;
        int p1 = left, p2 = mid + 1;
        int count = 0;
        while(p1 <= mid && p2 <= right){
            count += arr[p1] > arr[p2] ? (mid - p1 + 1) : 0;//如果p1所在下标的值大于p2，那么前半部分的所有值都大于p2所在下标的值，构成逆序对
            help[i++] = arr[p1] > arr[p2] ? arr[p2++] : arr[p1++];
        }
        while(p1 <= mid){
            help[i++] = arr[p1++];
        }
        while(p2 <= right){
            help[i++] = arr[p2++];
        }
        for(i = 0; i < help.length; i++){
            arr[left + i] = help[i];
        }
        return count;
    }
}
```

快排v3

```
public static void quickSort(int[] arr, int left, int right){
	if(left < right){
		swap(arr,left+(Math.Random() * (right - left  + 1)),right);
		int[] p = partation(arr,left,right);
		quickSort(arr, left,p[0] - 1);
		quickSort(arr,p[1] + 1, right);
	}
}
public static int[] partation(int[] arr, int left, int right){
	int less = left - 1;
	int more = right;
	while(left < more){
		if(arr[left] < arr[right]){
			swap(arr,++less,left++);
		}else if(arr[left] > arr[right]){
			swap(arr,--more,left);
		}else{
			left++;
		}
	}
	swap(arr,more,right);
}
public static void swap(int[] arr, int i, int j){
	int temp = arr[i];
	arr[i] = arr[j];
	arr[j] = temp;
}
