```
import java.util.ArrayList;
import java.util.List;

public class KMP {

    // 计算模式串的【最长相等前缀后缀数组】(Partial Match Table)
    private static int[] computePrefix(String pattern) {
        int m = pattern.length();
        int[] lps = new int[m];  // 前缀函数数组
        int len = 0;             // 当前已匹配的最长前后缀长度
        int i = 1;               // 从索引1开始计算（第0位无意义）

        while (i < m) {
            // 若当前字符与前缀的下一个字符匹配
            if (pattern.charAt(i) == pattern.charAt(len)) {
                len++;          // 扩展匹配长度
                lps[i] = len;   // 记录到lps数组
                i++;            // 移动到下一字符
            } else {
                if (len != 0) {
                    // 不匹配时，利用已计算的结果回退到更小的可能前缀
                    len = lps[len - 1];
                } else {
                    // 退到起点仍不匹配，则当前位置无共同前缀，设为0
                    lps[i] = 0;
                    i++;
                }
            }
        }
        return lps;
    }


    // KMP搜索算法：返回所有匹配的起始索引
    public static List<Integer> kmpSearch(String text, String pattern) {
        List<Integer> matches = new ArrayList<>();
        int n = text.length();
        int m = pattern.length();

        if (m == 0) {  // 模式为空时直接返回
            return matches;
        }

        int[] lps = computePrefix(pattern);  // 计算前缀数组
        int i = 0;  // 文本的当前指针
        int j = 0;  // 模式的当前指针

        while (i < n) {
            // 当前字符匹配时，移动双指针
            if (text.charAt(i) == pattern.charAt(j)) {
                i++;
                j++;
            }

            // 找到完全匹配的模式串
            if (j == m) {
                matches.add(i - j);  // 记录匹配位置
                j = lps[j - 1];      // 继续寻找下一个可能的匹配
            } 
            // 字符不匹配的情况
            else if (i < n && text.charAt(i) != pattern.charAt(j)) {
                if (j != 0) {
                    j = lps[j - 1];  // 回退模式串指针（关键！）
                } else {
                    i++;  // 模式串指针在起点，无法回退，移动文本指针
                }
            }
        }

        return matches;
    }

    // 测试代码
    public static void main(String[] args) {
        String text = "ABABDABACDABABCABAB";
        String pattern = "ABABCABAB";

        List<Integer> matches = kmpSearch(text, pattern);
        System.out.println("匹配起始位置: " + matches);  // 输出: [10]
    }
}

```

```java
import java.util.ArrayList;
import java.util.List;


public class KMP{

	public static int[] computePrefix(String pattern){
	 if(pattern.isEmpty()){
            return new int[0];
        }
		int[] next = new int[pattern.length()];
		int len = 0;
		next[0] = 0;
		for(int i = 1; i < pattern.length(); i++){
			if(pattern.charAt(i) == pattern.charAt(len)){
				len++;
			}
			while(len > 0 && pattern.charAt(i) != pattern.charAt(len)){
				len = next[len - 1];
			}
			next[i] = len;
		}
		return next;
	}

	public static List<Integer> KmpSearch(String text, String pattern){
		List<Integer> matches = new ArrayList<Integer>();
		int[] next = computePrefix(pattern);
		int j = 0,i = 0;
		while(i < text.length()){
				if(text.charAt(i) == pattern.chatAt(j)){
					i++;
					j++;
				}
				if(j == pattern.length()){
					matches.add(i - j);
					j = next[j - 1];
				}else if(text.charAt(i) != pattern.charAt(j)){
					if(j != 0){
						j = next[j - 1];
					}else{
						i++;
					}
				}
		}
		return matches;
	}
}
