```java
public static void radixSort(int[] arr, int left, int right, int digit){
	final int radix = 10;
	int i = 0,j = 0;
    int[] bucket = new int[R - L + 1];
    for(int d = 1; d <= digit; d++){ //最大有几位，就进桶出桶几次
    	int[] count = new int[radix];//用来计数

    	for(i = left; i <= right; i++){
    		j = getDigit(arr[i], d);
    		count[j]++;//此时count[j]的值表示的是第d位上的数是j，总共出现了几次
    	}
    	for(i = 1; i < radix; i++){
    		count[i] += count[i - 1];
    	}//求前缀和，count[i]的值表示小于等于i的数有多少个
    	for(i = right; i >= left; i--){//从后往前遍历数组第d位上的数，相当于出桶操作
    		j = getDigit(arr[i], d);
    		bucket[count[j] - 1] = arr[i]; //某个数在数组的位置，等于count（小于等于这个值的有多少个）上的值减1
    		count[j]--;//将count值减减
    	}
    	for(i = left, j = 0; i <= right; i++,j++){
    		arr[i] = bucket[j];//复制回原数组上
    	}
    }
}
public static int getDigit(int x, d){
	return ((x / ((int)Math.pow(10,d - 1)))%10);
}
public static int maxBits(int[] arr){
	int max = Integer.MIN_VALUE;
	for(int num : arr){
		max = num > max ? num : max;
	}
	int bits = 0;
	while(max != 0){
		bits++;
		max/=10;
	}
	return bits;
}
