/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    public boolean isPalindrome(ListNode head) {
        if(head == null || head.next == null){
            return true;
        }
        ListNode fast = head, pre_slow = head;
        while(fast.next != null && fast.next.next != null){
            fast = fast.next.next;
            pre_slow = pre_slow.next;
        }

        ListNode mid_right = pre_slow.next;
        pre_slow.next = null;

        ListNode revHead =  reverse(mid_right);
        ListNode p1 = head, p2 = revHead;
        while(p1 != null && p2 != null){
            if(p1.val != p2.val){
                return false;
            }
            p1 = p1.next;
            p2 = p2.next;
        }
        ListNode restoreHead = reverse(revHead);
            pre_slow.next = restoreHead;

        return true;
    }
    private static ListNode reverse(ListNode head){
        ListNode pre = null, cur = head;
        while(cur != null){
            ListNode temp = cur.next;

            cur.next = pre;
            pre = cur;
            cur = temp;
        }
        return pre;
    }
}
