class Solution {
    private Long prev = Long.MIN_VALUE; // 记录前驱节点的值

    public boolean isValidBST(TreeNode root) {
        if (root == null) return true;

        // 递归检查左子树
        if (!isValidBST(root.left)) {
            return false;
        }

        // 检查当前节点是否递增
        if (root.val <= prev) {
            return false;
        }

        // 更新前驱值
        prev = (long) root.val;

        // 递归检查右子树
        return isValidBST(root.right);
    }
}

