public boolean isFullTree(Node head){
	Info head = process(head);
	return head.nodeCount == (1 << head.height - 1);
}
public static class Info{
	int nodeCount;
	int height;
	public Info(int nodeCount, int height){
		this.nodeCount = nodeCount;
		this.height = height;
	}
}

public static Info process(Node head){
	if(head == null){
		return new Info(0,0);
	}
	Info leftData = process(head.left);
	Info rightData = process(head.right);

	int nodeCount = leftData.nodeCount + rightData.nodeCount + 1;
	int height = Math.max(leftData.height, rightData.height) + 1;
	return new Info(nodeCount, height);
}
