public static Node lowestFather(Node head, Node o1, Node o2){
	Map<Node, Node> fatherMap = new HashMap<Node,Node>();
	process(head,fatherMap);
	fatherMap.put(head, head);
	Set<Node> set1 = new HashSet<Node>();
	Node cur = o1;
	whiel(cur != fatherMap.get(cur)){
		set1.add(cur);
		cur = cur.get(cur);
	}
	cur = o2;
