	}
	return head;
}
public static void process(Node head, Map<Node, Node> fatherMap){
	if(head == null){
		return;
	}
	fatherMap.put(head.left, head);
	fatherMap.put(head.right, head);
	process(head.left);
	process(head.right);
}
